(* Standard ML (MLton): sum of the squares of the odd numbers 1 to 10 *)
val r = List.foldl op+ 0 (List.map (fn x => x * x) (List.filter (fn x => x mod 2 = 1) (List.tabulate (10, fn i => i + 1))));
val _ = print (Int.toString r ^ "\n");   (* prints 165 *)

