// Swift: an enum whose cases carry values, taken apart with switch
enum Shape { case square(Int); case rect(Int, Int) }
func area(_ s: Shape) -> Int {
    switch s {
    case .square(let side): return side * side
    case .rect(let w, let h): return w * h
    }
}
print(area(.square(3)) + area(.rect(2, 4)))   // prints 17

// Kotlin: a sealed class and an exhaustive when expression
sealed class Shape
class Square(val side: Int) : Shape()
class Rect(val w: Int, val h: Int) : Shape()
fun area(s: Shape): Int = when (s) {
    is Square -> s.side * s.side
    is Rect -> s.w * s.h
}
fun main() { println(area(Square(3)) + area(Rect(2, 4))) }   // prints 17

